// TimeZone: The clock a line item's daypart and frequency cap period are read on, a zone name of the IANA time zone database, such as `America/New_York` or `UTC`, or `viewer_local`, the clock where the ad renders. A zone name follows the zone's daylight saving rules, which a fixed offset doesn't.
type TimeZone string

var patternTimeZone = regexp.MustCompile(`^(viewer_local|[A-Z][A-Za-z0-9_+-]*(/[A-Za-z0-9_+-]+)*)$`)

// ValidateValue implements Value.
func (TimeZone) ValidateValue(v any, at string, errs *Errors) {
	s, ok := stringValue(v, at, errs)
	if !ok {
		return
	}
	checkPattern(s, patternTimeZone, at, errs)
}

// Timestamp: A point in time, written as an RFC 3339 date-time with a UTC offset, such as `2026-10-25T09:00:00Z`. It follows RFC 3339's grammar, with a `T` or `t` between the date and the time and an offset of `Z`, `z`, `+hh:mm`, or `-hh:mm`, never a space, `+05`, or `+0500`. Several spellings name one instant, such as `Z` and `+00:00`, so a receiver compares two Timestamps as instants, not as strings.
type Timestamp string

var patternTimestamp = regexp.MustCompile(`^[0-9]{4}-[0-9]{2}-[0-9]{2}[Tt][0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]+)?([Zz]|[+-][0-9]{2}:[0-9]{2})$`)

// ValidateValue implements Value.
func (Timestamp) ValidateValue(v any, at string, errs *Errors) {
	s, ok := stringValue(v, at, errs)
	if !ok {
		return
	}
	checkPattern(s, patternTimestamp, at, errs)
	checkFormat(s, "date-time", at, errs)
}

// Url: An absolute `https` URL that a receiver may fetch.
type Url string

var patternUrl = regexp.MustCompile(`^https://.+$`)

// ValidateValue implements Value.
func (Url) ValidateValue(v any, at string, errs *Errors) {
	s, ok := stringValue(v, at, errs)
	if !ok {
		return
	}
	checkPattern(s, patternUrl, at, errs)
	checkFormat(s, "uri", at, errs)
}

// VendorCode: A code that an AdCOM 1.0 list reserves for vendors, 500 or more, as List API Frameworks reserves "500+ Vendor-specific codes". It extends a vocabulary of the list's codes.
type VendorCode int64

// ValidateValue implements Value.
func (VendorCode) ValidateValue(v any, at string, errs *Errors) {
	r, ok := integerValue(v, at, errs)
	if !ok {
		return
	}
	checkMinimum(r, "500", false, at, errs)
}

// UnmarshalJSON decodes an integer written in any JSON spelling, such as 1.0 or 1e3.
func (n *VendorCode) UnmarshalJSON(data []byte) error {
	i, err := decodeInteger(data)
	if err != nil {
		return err
	}
	*n = VendorCode(i)
	return nil
}
